import { agentsManagedFiles } from '../tools/agents/index.js';
import { eslintManagedFiles } from '../tools/eslint/managed.js';
import { gitignoreManagedFiles } from '../tools/gitignore/index.js';
import { knipManagedFiles } from '../tools/knip/managed.js';
import { inspectPackageManifest, readCurrentDevtoolsVersion, syncPackageManifest, } from '../tools/package/index.js';
import { planBunDependencySync, syncBunDependencies, } from '../tools/package/syncBunDependencies.js';
import { prettierManagedFiles } from '../tools/prettier/managed.js';
import { inspectManagedFiles, resolveManagedTargetDirectory, syncManagedFiles, } from '../tools/shared/managedFiles.js';
import { inspectManagedSkills, syncManagedSkills } from '../tools/skills/managed.js';
import { vscodeManagedFiles } from '../tools/vscode/index.js';
import { workflowManagedFiles } from '../tools/workflows/index.js';
export async function runRepositoryCommand(command, argv, context) {
    try {
        const parsed = parseRepositoryArguments(argv, command.operation === 'sync');
        const targetDirectory = await resolveManagedTargetDirectory(context.cwd, parsed.targetPath);
        const devtoolsVersion = readCurrentDevtoolsVersion();
        return command.operation === 'status'
            ? await runStatus(command.scope, targetDirectory, devtoolsVersion, context)
            : await runSync(command.scope, targetDirectory, devtoolsVersion, parsed.dryRun, context);
    }
    catch (error) {
        context.writeStderr(`${getErrorMessage(error)}\n`);
        return { exitCode: 1 };
    }
}
export function parseRepositoryArguments(argv, allowDryRun) {
    let dryRun = false;
    let targetPath;
    for (const argument of argv) {
        if (argument === '--dry-run') {
            if (!allowDryRun) {
                throw new Error('--dry-run is only valid for sync commands.');
            }
            dryRun = true;
            continue;
        }
        if (argument.startsWith('-')) {
            throw new Error(`Unknown option: ${argument}`);
        }
        if (targetPath !== undefined) {
            throw new Error('Only one target path may be provided.');
        }
        targetPath = argument;
    }
    return { dryRun, targetPath };
}
async function runStatus(scope, targetDirectory, devtoolsVersion, context) {
    const statuses = [];
    if (scope === 'all' || scope === 'package') {
        statuses.push(await inspectPackageManifest(targetDirectory, devtoolsVersion));
    }
    statuses.push(...(await inspectManagedFiles(targetDirectory, getManagedFiles(scope))));
    if (scope === 'all' || scope === 'skills') {
        statuses.push(...(await inspectManagedSkills(targetDirectory, devtoolsVersion)));
    }
    writeStatusOutput(statuses, context);
    return { exitCode: statuses.some((status) => status.state !== 'current') ? 1 : 0 };
}
async function runSync(scope, targetDirectory, devtoolsVersion, dryRun, context) {
    const results = [];
    let packageDependenciesChanged = false;
    if (scope === 'all' || scope === 'package') {
        const packageResult = await syncPackageManifest(targetDirectory, devtoolsVersion, { dryRun });
        results.push(packageResult);
        packageDependenciesChanged = packageResult.action !== 'unchanged';
    }
    results.push(...(await syncManagedFiles(targetDirectory, getManagedFiles(scope), { dryRun })));
    if (scope === 'all' || scope === 'skills') {
        results.push(...(await syncManagedSkills(targetDirectory, devtoolsVersion, { dryRun })));
    }
    if (packageDependenciesChanged) {
        if (dryRun) {
            results.push(planBunDependencySync(targetDirectory));
        }
        else {
            const syncDependencies = context.syncDependencies ?? syncBunDependencies;
            results.push(await syncDependencies(targetDirectory));
        }
    }
    writeSyncOutput(results, context);
    return { exitCode: 0 };
}
function getManagedFiles(scope) {
    const definitionsByScope = {
        agents: agentsManagedFiles,
        eslint: eslintManagedFiles,
        knip: knipManagedFiles,
        prettier: prettierManagedFiles,
        skills: [],
        vscode: vscodeManagedFiles,
        workflows: workflowManagedFiles,
    };
    if (scope === 'all') {
        return [...Object.values(definitionsByScope).flat(), ...gitignoreManagedFiles];
    }
    if (scope === 'package') {
        return [];
    }
    return definitionsByScope[scope];
}
function writeStatusOutput(statuses, context) {
    for (const status of statuses) {
        if (status.state === 'current') {
            context.writeStdout(`✓ ${status.relativePath}\n`);
        }
        else if (status.state === 'missing') {
            context.writeStdout(`+ ${status.relativePath} missing\n`);
        }
        else if (status.state === 'obsolete') {
            context.writeStdout(`- ${status.relativePath} obsolete\n`);
        }
        else {
            context.writeStdout(`✗ ${status.relativePath} outdated\n`);
        }
    }
}
function writeSyncOutput(results, context) {
    for (const result of results) {
        const prefix = getActionPrefix(result.action);
        context.writeStdout(`${prefix} ${result.relativePath} ${formatAction(result.action)}\n`);
    }
}
function getActionPrefix(action) {
    if (action === 'unchanged') {
        return '✓';
    }
    if (action === 'created' || action === 'would-create') {
        return '+';
    }
    if (action === 'removed' || action === 'would-remove') {
        return '-';
    }
    return '↻';
}
function formatAction(action) {
    switch (action) {
        case 'created':
            return 'created';
        case 'updated':
            return 'updated';
        case 'removed':
            return 'removed';
        case 'unchanged':
            return 'unchanged';
        case 'would-create':
            return 'would create';
        case 'would-remove':
            return 'would remove';
        case 'would-update':
            return 'would update';
    }
}
function getErrorMessage(error) {
    return error instanceof Error ? error.message : String(error);
}
